// Metadata-only tool. Target PE files are never loaded as assemblies.
using System.Reflection;
using System.Reflection.Emit;
using System.Reflection.Metadata;
using System.Reflection.Metadata.Ecma335;
using System.Reflection.PortableExecutable;
using System.Security.Cryptography;
using System.Text.Json;
internal static class B49MetadataReview {
 static string Hash(byte[] b)=>Convert.ToHexString(SHA256.HashData(b)).ToLowerInvariant();
 static readonly Dictionary<ushort,OpCode> Ops=typeof(OpCodes).GetFields(BindingFlags.Public|BindingFlags.Static).Where(f=>f.FieldType==typeof(OpCode)).Select(f=>(OpCode)f.GetValue(null)!).ToDictionary(o=>unchecked((ushort)o.Value));
 static string TypeName(MetadataReader r,TypeDefinitionHandle h){var t=r.GetTypeDefinition(h);var d=t.GetDeclaringType();return d.IsNil?(r.GetString(t.Namespace)+"."+r.GetString(t.Name)).TrimStart('.'):TypeName(r,d)+"+"+r.GetString(t.Name);}
 static string Reference(MetadataReader r,EntityHandle h){try{return h.Kind switch {HandleKind.MethodDefinition=>Method(r,(MethodDefinitionHandle)h),HandleKind.MemberReference=>Member(r,(MemberReferenceHandle)h),HandleKind.TypeDefinition=>TypeName(r,(TypeDefinitionHandle)h),HandleKind.TypeReference=>r.GetString(r.GetTypeReference((TypeReferenceHandle)h).Namespace)+"."+r.GetString(r.GetTypeReference((TypeReferenceHandle)h).Name),HandleKind.MethodSpecification=>Reference(r,r.GetMethodSpecification((MethodSpecificationHandle)h).Method),_=>h.Kind+":"+MetadataTokens.GetToken(h).ToString("x8")};}catch{return "unresolved:"+MetadataTokens.GetToken(h).ToString("x8");}}
 static string Method(MetadataReader r,MethodDefinitionHandle h){var m=r.GetMethodDefinition(h);return TypeName(r,m.GetDeclaringType())+"::"+r.GetString(m.Name);}
 static string Member(MetadataReader r,MemberReferenceHandle h){var m=r.GetMemberReference(h);return Reference(r,m.Parent)+"::"+r.GetString(m.Name);}
 static object Inspect(string path){var bytes=File.ReadAllBytes(path);using var pe=new PEReader(new MemoryStream(bytes));var header=pe.PEHeaders;var result=new Dictionary<string,object?>{{"path",Path.GetFullPath(path)},{"sha256",Hash(bytes)},{"bytes",bytes.Length},{"machine",header.CoffHeader.Machine.ToString()},{"entryPointRva",header.PEHeader?.AddressOfEntryPoint},{"hasMetadata",pe.HasMetadata},{"targetAssemblyLoaded",false}};
 if(!pe.HasMetadata)return result;
 var r=pe.GetMetadataReader();result["mvid"]=r.GetGuid(r.GetModuleDefinition().Mvid).ToString();result["assembly"]=r.GetString(r.GetAssemblyDefinition().Name);var refs=r.AssemblyReferences.Select(h=>{var a=r.GetAssemblyReference(h);return new {name=r.GetString(a.Name),version=a.Version.ToString()};}).ToArray();result["assemblyReferences"]=refs;
 result["bclReferencesOnly"]=refs.All(a=>a.name.StartsWith("System.")||a.name=="System"||a.name=="netstandard"||a.name=="mscorlib"||a.name=="Microsoft.CSharp"||a.name=="Microsoft.Win32.Primitives");
 var methods=new List<object>();var pinvokes=new List<object>();var terminals=new List<object>();
 foreach(var th in r.TypeDefinitions){var type=r.GetTypeDefinition(th);var name=TypeName(r,th);foreach(var mh in type.GetMethods()){var m=r.GetMethodDefinition(mh);var id=Method(r,mh);if((m.Attributes&MethodAttributes.PinvokeImpl)!=0){var im=m.GetImport();pinvokes.Add(new {method=id,module=r.GetString(r.GetModuleReference(im.Module).Name),entry=r.GetString(im.Name)});}if(m.RelativeVirtualAddress==0)continue;var body=pe.GetMethodBody(m.RelativeVirtualAddress);var il=body.GetILBytes()??Array.Empty<byte>();var calls=new List<object>();var instructions=new List<object>();for(int i=0;i<il.Length;){int offset=i;ushort key=il[i++];if(key==0xfe)key=(ushort)(0xfe00|il[i++]);if(!Ops.TryGetValue(key,out var op))throw new InvalidDataException("unknown IL opcode");int size=op.OperandType switch {OperandType.InlineNone=>0,OperandType.ShortInlineBrTarget or OperandType.ShortInlineI or OperandType.ShortInlineVar=>1,OperandType.InlineVar=>2,OperandType.InlineI8 or OperandType.InlineR=>8,OperandType.InlineSwitch=>4+4*BitConverter.ToInt32(il,i),_=>4};string? operand=null;if(op.OperandType is OperandType.InlineMethod or OperandType.InlineField or OperandType.InlineType or OperandType.InlineTok){var token=MetadataTokens.EntityHandle(BitConverter.ToInt32(il,i));operand=Reference(r,token);if(op.OperandType==OperandType.InlineMethod)calls.Add(new {offset,op=op.Name,target=operand});}else if(op.OperandType==OperandType.InlineString){operand=r.GetUserString(MetadataTokens.UserStringHandle(BitConverter.ToInt32(il,i)&0xffffff));}instructions.Add(new {offset,op=op.Name,operand});i+=size;if(i>il.Length)throw new InvalidDataException("IL operand past end");}
 var row=new {method=id,token=MetadataTokens.GetToken(mh).ToString("x8"),ilSha256=Hash(il),ilBytes=il.Length,calls};methods.Add(row);if(name.Contains("HMController")||name.Contains("HMContext")||name.Contains("PsOwnershipCmReader")||name.EndsWith("Program+Fixture")||id.Contains("VerifyAsset")||id.Contains("ResolveVirtualEndpoint")||id.Contains("ManagedPsPnpObservation"))terminals.Add(new {method=id,ilSha256=Hash(il),instructions,calls});}}
 result["pinvokes"]=pinvokes;result["methodBodies"]=methods;result["terminalMethodBodies"]=terminals;result["reviewScope"]="Raw PE metadata and IL only; no target type initialization, Main, HostSession, pipe or SDK execution; terminal listing is source-bound inspection, not behavioral proof";return result;}
 static int Main(string[] args){if(args.Length<2||args[0]!="--out")return 2;var results=args.Skip(2).Select(Inspect).ToArray();File.WriteAllText(args[1],JsonSerializer.Serialize(new {status="METADATA_READ_ONLY",targetAssembliesLoaded=0,targets=results},new JsonSerializerOptions{WriteIndented=true}));return 0;}
}
